 10	
 11		"github.com/juhokoskela/pipedrive-go/pipedrive"
 12	)
 13	
 14	type File struct {
 15		ID          FileID          `json:"id,omitempty"`
 16		Name        string          `json:"name,omitempty"`
 17		FileName    string          `json:"file_name,omitempty"`
 18		FileType    string          `json:"file_type,omitempty"`
 19		FileSize    int             `json:"file_size,omitempty"`
 20		Description string          `json:"description,omitempty"`
 21		URL         string          `json:"url,omitempty"`
 22		UserID      *UserID         `json:"user_id,omitempty"`
 23		DealID      *DealID         `json:"deal_id,omitempty"`
 24		PersonID    *PersonID       `json:"person_id,omitempty"`
 25		OrgID       *OrganizationID `json:"org_id,omitempty"`
 26		ProductID   *ProductID      `json:"product_id,omitempty"`
 27		ActivityID  *ActivityID     `json:"activity_id,omitempty"`
 28		LeadID      *LeadID         `json:"lead_id,omitempty"`
 29		Active      bool            `json:"active_flag,omitempty"`
 30		Inline      bool            `json:"inline_flag,omitempty"`
 31		AddTime     *DateTime       `json:"add_time,omitempty"`
 32		UpdateTime  *DateTime       `json:"update_time,omitempty"`
 33	}
 34	
 35	type FilesService struct {
 36		client *Client
 37	}
 38	
 39	type FilesOption interface {
 40		applyFiles(*filesOptions)
 41	}
 42	
 43	type filesOptions struct {
 44		query          url.Values
 45		requestOptions []pipedrive.RequestOption
 46	}
 47	
 48	type filesOptionFunc func(*filesOptions)
 49	
 50	func (f filesOptionFunc) applyFiles(cfg *filesOptions) {
 51		f(cfg)
 52	}
 53	
 54	func WithFilesQuery(values url.Values) FilesOption {
 55		return filesOptionFunc(func(cfg *filesOptions) {
 56			cfg.query = mergeQueryValues(cfg.query, values)
 57		})
 58	}
 59	
 60	func WithFilesRequestOptions(opts ...pipedrive.RequestOption) FilesOption {
 61		return filesOptionFunc(func(cfg *filesOptions) {
 62			cfg.requestOptions = append(cfg.requestOptions, opts...)
 63		})
 64	}
 65	
 66	func newFilesOptions(opts []FilesOption) filesOptions {
 67		var cfg filesOptions
 68		for _, opt := range opts {
 69			if opt == nil {
 70				continue
 71			}
 72			opt.applyFiles(&cfg)
 73		}
 74		return cfg
 75	}
 76	
 77	func (s *FilesService) List(ctx context.Context, opts ...FilesOption) ([]File, *Pagination, error) {
 78		cfg := newFilesOptions(opts)
 79	
 80		var payload struct {
 81			Data           []File `json:"data"`
 82			AdditionalData *struct {
 83				Pagination *Pagination `json:"pagination"`
 84			} `json:"additional_data"`
 85		}
 86		if err := s.client.Raw.Do(ctx, http.MethodGet, "/files", cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
 87			return nil, nil, err
 88		}
 89		var page *Pagination
 90		if payload.AdditionalData != nil {
 91			page = payload.AdditionalData.Pagination
 92		}
 93		return payload.Data, page, nil
 94	}
 95	
 96	func (s *FilesService) Get(ctx context.Context, id FileID, opts ...FilesOption) (*File, error) {
 97		if err := validateID(id, "file id"); err != nil {
 98			return nil, err
 99		}
100		cfg := newFilesOptions(opts)
101		path := fmt.Sprintf("/files/%d", id)
102	
103		var payload struct {
104			Data *File `json:"data"`
105		}
106		if err := s.client.Raw.Do(ctx, http.MethodGet, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
107			return nil, err
108		}
109		if payload.Data == nil {
110			return nil, fmt.Errorf("missing file data in response")
111		}
112		return payload.Data, nil
113	}
114	
115	func (s *FilesService) Add(ctx context.Context, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
116		cfg := newFilesOptions(opts)
117		if body == nil {
118			return nil, fmt.Errorf("file body is required")
119		}
120		if contentType == "" {
121			return nil, fmt.Errorf("content type is required")
122		}
123	
124		reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
125		reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))
126	
127		var payload struct {
128			Data *File `json:"data"`
129		}
130		if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
131			return nil, err
132		}
133		if payload.Data == nil {
134			return nil, fmt.Errorf("missing file data in response")
135		}
136		return payload.Data, nil
137	}
138	
139	func (s *FilesService) AddRemoteFile(ctx context.Context, form url.Values, opts ...FilesOption) (*File, error) {
140		cfg := newFilesOptions(opts)
141		if len(form) == 0 {
142			return nil, fmt.Errorf("form values are required")
143		}
144	
145		body := strings.NewReader(form.Encode())
146		reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
147		reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", "application/x-www-form-urlencoded"))
148	
149		var payload struct {
150			Data *File `json:"data"`
151		}
152		if err := s.client.Raw.Do(ctx, http.MethodPost, "/files/remote", cfg.query, body, &payload, reqOpts...); err != nil {
153			return nil, err
154		}
155		if payload.Data == nil {
156			return nil, fmt.Errorf("missing remote file data in response")
157		}
158		return payload.Data, nil
159	}
160	
161	func (s *FilesService) LinkRemoteFile(ctx context.Context, form url.Values, opts ...FilesOption) (*File, error) {
162		cfg := newFilesOptions(opts)
