171		var payload struct {
172			Data *File `json:"data"`
173		}
174		if err := s.client.Raw.Do(ctx, http.MethodPost, "/files/remoteLink", cfg.query, body, &payload, reqOpts...); err != nil {
175			return nil, err
176		}
177		if payload.Data == nil {
178			return nil, fmt.Errorf("missing linked file data in response")
179		}
180		return payload.Data, nil
181	}
182	
183	func (s *FilesService) Update(ctx context.Context, id FileID, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
184		if err := validateID(id, "file id"); err != nil {
185			return nil, err
186		}
187		cfg := newFilesOptions(opts)
188		if body == nil {
189			return nil, fmt.Errorf("file body is required")
190		}
191		if contentType == "" {
192			return nil, fmt.Errorf("content type is required")
193		}
194	
195		reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
196		reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))
197	
198		path := fmt.Sprintf("/files/%d", id)
199		var payload struct {
200			Data *File `json:"data"`
201		}
202		if err := s.client.Raw.Do(ctx, http.MethodPut, path, cfg.query, body, &payload, reqOpts...); err != nil {
203			return nil, err
204		}
205		if payload.Data == nil {
206			return nil, fmt.Errorf("missing file update data in response")
207		}
208		return payload.Data, nil
209	}
210	
211	func (s *FilesService) Delete(ctx context.Context, id FileID, opts ...FilesOption) (bool, error) {
212		if err := validateID(id, "file id"); err != nil {
213			return false, err
214		}
215		cfg := newFilesOptions(opts)
216		path := fmt.Sprintf("/files/%d", id)
217	
218		var payload struct {
219			Success *bool `json:"success"`
220		}
221		if err := s.client.Raw.Do(ctx, http.MethodDelete, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
222			return false, err
223		}
224		if payload.Success == nil {
225			return false, fmt.Errorf("missing file delete success in response")
226		}
227		return *payload.Success, nil
228	}
229	
230	func (s *FilesService) Download(ctx context.Context, id FileID, opts ...FilesOption) ([]byte, error) {
231		if err := validateID(id, "file id"); err != nil {
232			return nil, err
233		}
234		cfg := newFilesOptions(opts)
235		ctx, editors := pipedrive.ApplyRequestOptions(ctx, cfg.requestOptions...)
236	
237		resp, err := s.client.gen.DownloadFile(ctx, int(id), toRequestEditors(editors)...)
238		if err != nil {
239			return nil, err
240		}
241		defer resp.Body.Close()
242		body, err := io.ReadAll(resp.Body)
243		if err != nil {
244			return nil, fmt.Errorf("read response: %w", err)
245		}
246		if resp.StatusCode < 200 || resp.StatusCode > 299 {
247			return nil, errorFromResponse(resp, body)
248		}
249		return body, nil
250	}
251	
252	func (s *FilesService) DownloadTo(ctx context.Context, id FileID, dst io.Writer, opts ...FilesOption) error {
253		if err := validateID(id, "file id"); err != nil {
254			return err
255		}
256		if dst == nil {
257			return fmt.Errorf("download destination is required")
258		}
259	
260		cfg := newFilesOptions(opts)
261		reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
262		reqOpts = append(reqOpts, pipedrive.WithNoResponseSizeLimit())
263		ctx, editors := pipedrive.ApplyRequestOptions(ctx, reqOpts...)
264	
265		resp, err := s.client.gen.DownloadFile(ctx, int(id), toRequestEditors(editors)...)
266		if err != nil {
267			return err
268		}
269		defer resp.Body.Close()
270	
271		if resp.StatusCode < 200 || resp.StatusCode > 299 {
272			body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
273			if err != nil {
274				return fmt.Errorf("read response: %w", err)
275			}
276			return errorFromResponse(resp, body)
277		}
278		if _, err := io.Copy(dst, resp.Body); err != nil {
279			return fmt.Errorf("write download: %w", err)
280		}
281		return nil
282	}

