 12		"github.com/juhokoskela/pipedrive-go/internal/multipartbody"
 13		"github.com/juhokoskela/pipedrive-go/pipedrive"
 14	)
 15	
 16	type CallLogOutcome string
 17	
 18	const (
 19		CallLogOutcomeConnected     CallLogOutcome = "connected"
 20		CallLogOutcomeNoAnswer      CallLogOutcome = "no_answer"
 21		CallLogOutcomeLeftMessage   CallLogOutcome = "left_message"
 22		CallLogOutcomeLeftVoicemail CallLogOutcome = "left_voicemail"
 23		CallLogOutcomeWrongNumber   CallLogOutcome = "wrong_number"
 24		CallLogOutcomeBusy          CallLogOutcome = "busy"
 25	)
 26	
 27	type CallLog struct {
 28		ID             CallLogID       `json:"id"`
 29		ActivityID     *ActivityID     `json:"activity_id,omitempty"`
 30		Subject        string          `json:"subject,omitempty"`
 31		Duration       string          `json:"duration,omitempty"`
 32		Outcome        CallLogOutcome  `json:"outcome,omitempty"`
 33		FromPhone      string          `json:"from_phone_number,omitempty"`
 34		ToPhone        string          `json:"to_phone_number,omitempty"`
 35		StartTime      *DateTime       `json:"start_time,omitempty"`
 36		EndTime        *DateTime       `json:"end_time,omitempty"`
 37		PersonID       *PersonID       `json:"person_id,omitempty"`
 38		OrganizationID *OrganizationID `json:"org_id,omitempty"`
 39		DealID         *DealID         `json:"deal_id,omitempty"`
 40		LeadID         *LeadID         `json:"lead_id,omitempty"`
 41		UserID         *UserID         `json:"user_id,omitempty"`
 42		CompanyID      *int            `json:"company_id,omitempty"`
 43		HasRecording   bool            `json:"has_recording,omitempty"`
 44		Note           string          `json:"note,omitempty"`
 45	}
 46	
 47	type CallLogsPagination struct {
 48		Start                 int  `json:"start,omitempty"`
 49		Limit                 int  `json:"limit,omitempty"`
 50		MoreItemsInCollection bool `json:"more_items_in_collection,omitempty"`
 51		NextStart             *int `json:"next_start,omitempty"`
 52	}
 53	
 54	type CallLogsService struct {
 55		client *Client
 56	}
