 15	func TestFilesService_List(t *testing.T) {
 16		t.Parallel()
 17	
 18		client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
 19			if r.Method != http.MethodGet {
 20				t.Fatalf("unexpected method: %s", r.Method)
 21			}
 22			if r.URL.Path != "/files" {
 23				t.Fatalf("unexpected path: %s", r.URL.Path)
 24			}
 25			if got := r.URL.Query().Get("limit"); got != "1" {
 26				t.Fatalf("unexpected limit: %q", got)
 27			}
 28			if got := r.Header.Get("X-Test"); got != "1" {
 29				t.Fatalf("unexpected header X-Test: %q", got)
 30			}
 31	
 32			w.Header().Set("Content-Type", "application/json")
 33			_, _ = w.Write([]byte(`{"success":true,"data":[{"id":1,"name":"doc.pdf"}],"additional_data":{"pagination":{"start":0,"limit":1,"more_items_in_collection":false}}}`))
 34		})
 35	
 36		query := url.Values{}
 37		query.Set("limit", "1")
 38		files, page, err := client.Files.List(
 39			context.Background(),
 40			WithFilesQuery(query),
 41			WithFilesRequestOptions(pipedrive.WithHeader("X-Test", "1")),
 42		)
 43		if err != nil {
 44			t.Fatalf("List error: %v", err)
 45		}
